/* ---------- panel ---------- */
async function loadFin(){const N=$('finNav');N.innerHTML=xlNav();
  $('finMain').innerHTML='<div class="empty">در حال بارگذاری…</div>';try{await finCat(true);await finRender()}catch(e){$('finMain').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function finRender(){document.querySelectorAll('[data-fsec]').forEach(b=>b.setAttribute('aria-current',b.dataset.fsec===FIN.sec));const M=$('finMain'),s=FIN.sec;
  const head=t=>`<div class="qhead"><h2>${esc(t)}</h2></div><div class="msg" id="finMsg"></div>`;M.innerHTML=head(xlSecName(s))+'<div id="finB"><div class="empty">در حال بارگذاری…</div></div>';
  try{await (FREND[s]||(()=>{}))($('finB'))}catch(e){$('finB').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
const FREND={};
/* dashboard */
FREND.dash=async B=>{const [y,m]=jYM(),months=[];for(let i=5;i>=0;i--){let yy=y,mm=m-i;while(mm<1){mm+=12;yy--}months.push(jmRange(yy,mm))}
  const j=await api('finDash',{months:months.map(x=>({k:x.k,from:x.from,to:x.to}))}),g=k=>(j.pl.find(x=>x.g===k)||{}).v||0,inc=g('4'),cost=-(g('5')+g('6')),cashB=j.balances.reduce((a,b)=>a+b.b,0);
  const mx=Math.max(1,...j.months.map(x=>Math.max(x.inc,x.exp)));
  B.innerHTML=`<div class="kpis fk"><div class="kpi"><b>${nf(cashB)}</b><span>موجودی صندوق، بانک و کارتخوان</span></div><div class="kpi"><b>${nf(j.ar)}</b><span>طلب از بیماران</span></div><div class="kpi"><b>${nf(j.docPay)}</b><span>بدهی سهم پزشکان و همکاران</span></div>
    <div class="kpi"><b>${nf(inc-cost)}</b><span>سود ۳۰ روز اخیر (درآمد ${nf(inc)} − هزینه ${nf(cost)})</span></div><div class="kpi"><b>${nf(j.chqIn.s)}</b><span>${fa(j.chqIn.n)} چک دریافتنی تا ۷ روز آینده</span></div><div class="kpi"><b>${nf(j.chqOut.s)}</b><span>${fa(j.chqOut.n)} چک پرداختنی تا ۷ روز آینده</span></div></div>
    <div class="fcols"><section class="card"><h3>درآمد و هزینه‌ی ۶ ماه اخیر</h3><div class="fbars">${j.months.map((x,i)=>`<div class="fbr"><span>${esc(months[i].l)}</span><div><i class="in" style="width:${Math.round(x.inc*100/mx)}%"></i><i class="ex" style="width:${Math.round(x.exp*100/mx)}%"></i></div><small>${nf(x.inc)} / ${nf(x.exp)}</small></div>`).join('')}</div><p class="note"><i class="lg in"></i> درآمد خالص <i class="lg ex"></i> هزینه</p>
      ${FT('fdM','درآمد و هزینه‌ی ماهانه',[{k:'l',l:'ماه'},{k:'inc',l:'درآمد',t:'m'},{k:'exp',l:'هزینه',t:'m'},{k:'p',l:'سود',t:'m'}],j.months.map((x,i)=>({l:months[i].l,inc:x.inc,exp:x.exp,p:x.inc-x.exp})),{sum:['inc','exp','p']})}</section>
    <section class="card">${FT('fdB','موجودی حساب‌های نقد و بانک',[{k:'name',l:'حساب'},{k:'acc',l:'کد'},{k:'b',l:'مانده',t:'m'}],j.balances,{sum:['b']})}</section></div>`};
/* invoices */
FREND.inv=async B=>{const p=FIN.per.inv||(FIN.per.inv=perRange('m'));const j=await api('finInvList',Object.assign({q:FIN.invq||''},p));const I=j.items;
  B.innerHTML=`<div class="btns" style="flex-wrap:wrap"><button class="btn" type="button" id="fiNew">+ صورتحساب تازه</button><input id="fiQ" type="search" placeholder="جستجو: نام، کد ملی، موبایل، شماره" value="${esc(FIN.invq||'')}" style="max-width:280px"></div>${perHTML('inv')}
  ${FT('fInv','صورتحساب‌های مراجعه',[{k:'no',l:'شماره',t:'n'},{k:'day',l:'تاریخ',t:'d'},{k:'pname',l:'بیمار'},{k:'srv',l:'خدمات',v:r=>r.lines.map(l=>l.name+(l.qty>1?' ×'+l.qty:'')).join('، ')},{k:'total',l:'جمع خدمات',t:'m'},{k:'discC',l:'تخفیف کلینیک',t:'m'},{k:'discD',l:'تخفیف پزشک',t:'m'},{k:'parts',l:'قطعات',t:'m'},{k:'net',l:'خالص',t:'m'},
    {k:'fees',l:'سهم پزشکان',t:'m'},{k:'by',l:'ثبت'},{k:'st',l:'وضعیت',v:r=>r.st==='void'?'باطل':'ثبت شده'}],I,{sum:['total','discC','discD','parts','net','fees'],sub:perSub('inv'),rc:r=>r.st==='void'?'void':'',act:r=>`<button class="btn sm ghost" data-fiprt="${esc(r.id)}">چاپ</button>${r.st!=='void'?`<button class="btn sm ghost" data-fied="${esc(r.id)}">ویرایش</button><button class="btn sm ghost" data-fivd="${esc(r.id)}">ابطال</button>`:''}`})}`;FIN.invItems=I};
async function fiOpen(o={}){await finCat();const pl=ROLE==='staff'?null:await finPlans().catch(()=>null);
  FIN.inv=Object.assign({id:'',day:tDay(),plan:'',pname:'',nid:'',phone:'',pfile:'',lines:[],discC:0,discD:0,parts:0,note:'',pays:[],bal:null,sendId:uuid()},o);
  const s=mkSheet('fiSheet',`<h3 id="fiT">${o.xl?'۱ · فرم ثبت':o.id?'ویرایش صورتحساب':'صورتحساب مراجعه'}</h3><div id="fiB"></div><div class="msg" id="fiMsg"></div>
    <div class="btns" style="flex-wrap:wrap"><button class="btn" type="button" id="fiSave">ثبت صورتحساب</button><button class="btn ghost" type="button" id="fiSugg">پیشنهاد از کارهای این روز</button><button class="btn ghost" type="button" id="fiClose">بستن</button></div>`);s.hidden=false;s.classList.add('wide');fiDraw();
  if(FIN.inv.plan&&!o.id)fiSuggest(true)}
function fiDraw(){if(FIN.inv&&FIN.inv.xl){xfDraw();return}const v=FIN.inv,C=FIN.cat,staff=XL_LITE(),SV=C.svc.filter(x=>x.active),PY=C.payees.filter(x=>x.active),docs=PY.filter(x=>x.kind!=='clinic');
  const fee=(s,p)=>((C.fees||[]).find(f=>f.svc===s&&f.payee===p)||{}).amount||0;
  const rows=v.lines.map((l,i)=>{const s=SV.find(x=>x.id===l.svc)||{},price=l.price!==undefined&&l.price!==''?l.price:s.price,amt=Math.round((Number(price)||0)*(Number(l.qty)||0)),f=l.fee0?0:fee(l.svc,l.payee)*(Number(l.qty)||0);l._amt=amt;l._fee=f;
    return `<tr><td><select data-fil="svc" data-i="${i}"><option value="">— خدمت —</option>${SV.map(x=>`<option value="${esc(x.id)}"${x.id===l.svc?' selected':''}>${esc(x.name)}</option>`).join('')}</select>${l.why?`<small class="note">${esc(l.why)}</small>`:''}</td>
      <td>${s.rule==='clinic'?`<span class="note">سهم: کلینیک</span><select data-fil="init" data-i="${i}"><option value="">— پزشک اولیه —</option>${docs.map(p=>`<option value="${esc(p.id)}"${p.id===l.init?' selected':''}>${esc(p.name)}</option>`).join('')}</select>`:`<select data-fil="payee" data-i="${i}"><option value="">— پزشک/همکار —</option>${PY.map(p=>`<option value="${esc(p.id)}"${p.id===l.payee?' selected':''}>${esc(p.name)}</option>`).join('')}</select>`}</td>
      <td><input data-fil="qty" data-i="${i}" inputmode="decimal" value="${esc(fa(l.qty||''))}" style="width:60px"></td><td><input class="mny" data-fil="price" data-i="${i}" inputmode="numeric" value="${price?fa(price):''}" style="width:120px"></td><td class="num">${nf(amt)}</td>${staff?'':`<td class="num">${nf(f)}</td>`}<td><button type="button" class="btn sm ghost" data-fidel="${i}">✕</button></td></tr>`}).join('');
  const total=v.lines.reduce((a,l)=>a+(l._amt||0),0),fees=v.lines.reduce((a,l)=>a+(l._fee||0),0),net=total-v.discC-v.discD+v.parts,paid=v.pays.reduce((a,p)=>a+(Number(p.amount)||0),0),bal=v.bal||0;
  $('fiB').innerHTML=`<div class="fields"><label class="f">تاریخ<input id="fi_day" inputmode="numeric" value="${esc(jDay(v.day))}"></label>
    <label class="f">بیمار<input id="fi_pn" list="fiPl" value="${esc(v.pname)}" placeholder="جستجو در بیماران یا نام تازه" autocomplete="off"${v.id?' disabled':''}></label><datalist id="fiPl">${(FIN.pl||[]).slice(0,4000).map(p=>`<option value="${esc(p.name)}${p.nid?' · '+esc(p.nid):''}">`).join('')}</datalist>
    <label class="f">کد ملی<input id="fi_nid" inputmode="numeric" value="${esc(v.nid)}"></label><label class="f">موبایل<input id="fi_ph" inputmode="tel" value="${esc(v.phone)}"></label><label class="f">شماره پرونده / گرافی<input id="fi_pf" value="${esc(v.pfile)}"></label></div>
    ${v.plan?'<p class="note">بیمار از پرونده‌های سایت انتخاب شده است.</p>':''}
    <div class="ftsc"><table class="tbl ftbl fiT"><thead><tr><th>خدمت</th><th>پزشک / همکار</th><th>تعداد</th><th class="num">تعرفه‌ی بیمار</th><th class="num">مبلغ</th>${staff?'':'<th class="num">سهم پزشک</th>'}<th></th></tr></thead><tbody>${rows||`<tr><td colspan="7" class="empty">ردیفی نیست؛ «افزودن خدمت» یا «پیشنهاد از کارهای این روز» را بزنید.</td></tr>`}</tbody></table></div>
    <div class="btns"><button type="button" class="btn sm ghost" id="fiAdd">+ افزودن خدمت</button></div>
    <div class="fsum"><div class="fields"><label class="f">تخفیف سهم کلینیک${mnyIn('fi_dc',v.discC)}</label><label class="f">تخفیف سهم پزشک${mnyIn('fi_dd',v.discD)}</label><label class="f">فروش قطعات${mnyIn('fi_pt',v.parts)}</label></div>
      <table class="tbl"><tbody><tr><td>کل هزینه‌ی درمان</td><td class="num">${nf(total)}</td></tr><tr><td>مانده سهم کلینیک (بعد از تخفیف)</td><td class="num">${nf(total-v.discC-v.discD)}</td></tr>${staff?'':`<tr><td>جمع سهم پزشکان (قبل از تخفیف پزشک)</td><td class="num">${nf(fees)}</td></tr>`}
        <tr><td>${bal>=0?'بدهکاری قبلی':'بستانکاری قبلی'}</td><td class="num">${v.bal===null?'—':nf(Math.abs(bal))}</td></tr><tr><td><b>مبلغ این صورتحساب</b></td><td class="num"><b>${nf(net)}</b></td></tr><tr><td>دریافت همین حالا</td><td class="num">${nf(paid)}</td></tr><tr><td><b>مانده‌ی نسیه</b></td><td class="num"><b>${nf(bal+net-paid)}</b></td></tr></tbody></table></div>
    <h3 class="pf-h">دریافت همین حالا</h3><div id="fiPays">${v.pays.map((p,i)=>`<div class="fields fpay"><label class="f">نوع<select data-fip="kind" data-i="${i}"><option value="cash"${p.kind==='cash'?' selected':''}>نقد</option><option value="card"${p.kind==='card'?' selected':''}>کارتخوان</option><option value="chq"${p.kind==='chq'?' selected':''}>چک</option></select></label>
      <label class="f">مبلغ<input class="mny" data-fip="amount" data-i="${i}" inputmode="numeric" value="${p.amount?fa(p.amount):''}"></label>${fx3PayX(p,i)}${p.kind==='chq'?`<label class="f">سررسید<input data-fip="due" data-i="${i}" inputmode="numeric" value="${esc(p.dueJ||'')}" placeholder="۱۴۰۵/۰۹/۰۱"></label><label class="f">شماره چک<input data-fip="no" data-i="${i}" value="${esc(p.no||'')}"></label><label class="f">بانک<input data-fip="bank" data-i="${i}" value="${esc(p.bank||'')}"></label>`:''}<button type="button" class="btn sm ghost" data-fipd="${i}">✕</button></div>`).join('')}</div>
    <div class="btns"><button type="button" class="btn sm ghost" data-fipa="cash">+ نقد</button><button type="button" class="btn sm ghost" data-fipa="card">+ کارتخوان</button><button type="button" class="btn sm ghost" data-fipa="chq">+ چک</button></div>
    <label class="f full">توضیحات<input id="fi_note" value="${esc(v.note)}"></label>`}
function fiRead(){const v=FIN.inv;v.day=parseJ($('fi_day').value.trim())||v.day;v.nid=toEn($('fi_nid').value.trim());v.phone=toEn($('fi_ph').value.trim());v.pfile=$('fi_pf').value.trim();v.note=$('fi_note').value.trim();v.discC=mv('fi_dc');v.discD=mv('fi_dd');v.parts=mv('fi_pt');
  if(!v.id&&!v.xl){const t=$('fi_pn').value.trim(),nm=t.split(' · ')[0],nid=t.split(' · ')[1]||'';const p=(FIN.pl||[]).find(x=>x.name===nm&&(!nid||x.nid===nid));if(p&&p.id!==v.plan){v.plan=p.id;v.pname=p.name;if(!v.nid)v.nid=p.nid;v.bal=null;fiSuggest(true)}else if(!p){if(v.plan&&nm!==v.pname)v.plan='';v.pname=nm}}}
async function fiSuggest(quiet){const v=FIN.inv;if(!v.plan){if(!quiet)finIMsg('برای پیشنهاد، بیمار را از پرونده‌های سایت انتخاب کنید.',1);return}
  try{const j=await api('finSuggest',{id:v.plan,day:v.day});v.bal=j.balance;if(!v.phone)v.phone=j.patient.phone;if(!v.nid)v.nid=j.patient.nid;v.pname=j.patient.name;
    if(j.lines.length&&!v.lines.length)v.lines=j.lines;else if(j.lines.length&&!quiet){j.lines.forEach(l=>{if(!v.lines.some(x=>x.svc===l.svc&&x.payee===l.payee&&(x.why||'')===(l.why||'')))v.lines.push(l)})}
    fiDraw();finIMsg(j.lines.length?fa(j.lines.length)+' ردیف از کارهای ثبت‌شده‌ی این روز پیشنهاد شد؛ بررسی کنید.':quiet?'':'برای این روز کار ثبت‌شده‌ای در جراحی یا پروتز پیدا نشد.')}catch(e){finIMsg(e.message,1)}}
function finIMsg(t,bad){const m=$('fiMsg');if(m){m.className='msg '+(bad?'err':'ok');m.textContent=t}}
function fiPrintDoc(iv){const L=iv.lines||[];return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>صورتحساب ${esc(iv.pname)}</title><style>@page{size:A5;margin:9mm}body{font-family:Vazirmatn,Tahoma,sans-serif;font-size:11px;color:#111}
  .hd{display:flex;justify-content:space-between;border-bottom:2px solid #0a7680;padding-bottom:5px;margin-bottom:8px}.hd b{font-size:14px;color:#0a7680}table{width:100%;border-collapse:collapse;margin-top:6px}th,td{border:1px solid #bbb;padding:3px 5px;text-align:right}th{background:#e6f1f1}.num{text-align:left;white-space:nowrap}.t td{border:0;border-bottom:1px dotted #bbb}.sg{display:flex;justify-content:space-around;margin-top:24px}</style></head><body>
  <div class="hd"><div><b>${esc(SET.clinic||'')}</b><br>صورتحساب بیمار</div><div>شماره: ${esc(fa(iv.no||''))}<br>تاریخ: ${esc(jDay(iv.day))}</div></div>
  <div>نام بیمار: <b>${esc(iv.pname)}</b>${iv.nid?' · کد ملی: '+esc(iv.nid):''}${iv.pfile?' · پرونده: '+esc(iv.pfile):''}</div>
  <table><thead><tr><th>خدمت</th><th>پزشک</th><th>تعداد</th><th class="num">تعرفه</th><th class="num">مبلغ</th></tr></thead><tbody>${L.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.pname==='کلینیک'&&l.initName?'(اولیه: '+l.initName+')':l.pname)}</td><td>${fa(l.qty)}</td><td class="num">${nf(l.price)}</td><td class="num">${nf(l.amt)}</td></tr>`).join('')}</tbody></table>
  <table class="t"><tr><td>کل هزینه‌ی درمان</td><td class="num">${nf(iv.total)}</td></tr>${iv.discC+iv.discD?`<tr><td>تخفیف</td><td class="num">${nf(iv.discC+iv.discD)}</td></tr>`:''}${iv.parts?`<tr><td>فروش قطعات</td><td class="num">${nf(iv.parts)}</td></tr>`:''}<tr><td><b>قابل پرداخت</b></td><td class="num"><b>${nf(iv.net)}</b> تومان</td></tr></table>
  ${iv.note?`<p>توضیحات: ${esc(iv.note)}</p>`:''}<div class="sg"><span>امضای بیمار</span><span>مهر و امضای کلینیک</span></div></body></html>`}
async function fiSave(t){fiRead();const v=FIN.inv;for(const p of v.pays){if(p.kind==='chq'){p.due=parseJ(p.dueJ||'');if(!p.due){finIMsg('سررسید چک را درست بنویسید (مثل ۱۴۰۵/۰۹/۰۱).',1);return}}}
  t.disabled=true;finIMsg('در حال ثبت…');try{const j=await api('finInvSave',{inv:{id:v.id,sendId:v.sendId,day:v.day,plan:v.plan,pname:v.pname,nid:v.nid,phone:v.phone,pfile:v.pfile,discC:v.discC,discD:v.discD,parts:v.parts,note:v.note,
      lines:v.lines.map(l=>({svc:l.svc,payee:l.payee,qty:l.qty,price:l.price,amtFix:l.amtFix,init:l.init,fee0:l.fee0,why:l.why})),pays:v.pays.map(p=>({kind:p.kind,amount:p.amount,due:p.due,no:p.no,bank:p.bank,part:p.part||'s',pos:p.kind==='card'?p.pos||'':''}))}});
    $('fiSheet').hidden=true;toast('صورتحساب ثبت شد.');const L=await api('finInvList',{party:v.plan?'p:'+v.plan:undefined,from:v.day,to:v.day}).catch(()=>null);const iv=L&&L.items.find(x=>x.id===j.id);if(iv)printHTML(fiPrintDoc(iv));if(!$('viewFin').hidden&&(FIN.sec==='inv'||FIN.sec==='xform'))finRender()}
  catch(e){finIMsg(e.message,1)}finally{t.disabled=false}}
document.addEventListener('change',e=>{const t=e.target;if(!FIN.inv||!t.dataset)return;const i=+t.dataset.i;
  if(t.dataset.fil){fiRead();const l=FIN.inv.lines[i];if(!l)return;if(t.dataset.fil==='svc'){l.svc=t.value;l.price=undefined}else if(t.dataset.fil==='qty'){l.qty=Number(toEn(t.value))||0;delete l.amtFix}else if(t.dataset.fil==='amt')l.amtFix=mvv(t.value);else if(t.dataset.fil==='price')l.price=mvv(t.value);else l[t.dataset.fil]=t.value;fiDraw();return}
  if(t.dataset.fip){fiRead();const p=FIN.inv.pays[i];if(!p)return;const k=t.dataset.fip;if(k==='amount')p.amount=mvv(t.value);else if(k==='due')p.dueJ=t.value.trim();else p[k]=t.value;if(k==='kind')fiDraw();else fiDraw();return}
  if(t.id==='fi_pn'||t.id==='fi_dc'||t.id==='fi_dd'||t.id==='fi_pt'){fiRead();fiDraw()}});
const mvv=s=>parseInt(toEn(s||'').replace(/[^\d]/g,''),10)||0;
document.addEventListener('click',async e=>{const t=e.target.closest&&e.target.closest('button,[data-finv]');if(!t)return;
  if(t.dataset.finv){e.preventDefault();try{$('pfSheet').hidden=true}catch(x){}xfOpenId(t.dataset.finv,tDay()).catch(err=>toast(err.message,1));return}
  if(t.id==='fiNew'){fiOpen();return}
  if(t.id==='fiClose'){$('fiSheet').hidden=true;FIN.inv=null;return}
  if(t.id==='fiAdd'){fiRead();FIN.inv.lines.push({svc:'',payee:'',qty:1});fiDraw();return}
  if(t.dataset.fidel!==undefined){fiRead();FIN.inv.lines.splice(+t.dataset.fidel,1);fiDraw();return}
  if(t.dataset.fipa){fiRead();FIN.inv.pays.push({kind:t.dataset.fipa,amount:0});fiDraw();return}
  if(t.dataset.fipd!==undefined){fiRead();FIN.inv.pays.splice(+t.dataset.fipd,1);fiDraw();return}
  if(t.id==='fiSugg'){fiRead();fiSuggest(false);return}
  if(t.id==='fiSave'){fiSave(t);return}
  if(t.dataset.fiprt){const iv=(FIN.invItems||[]).find(x=>x.id===t.dataset.fiprt);if(iv)printHTML(fiPrintDoc(iv));return}
  if(t.dataset.fied){const iv=(FIN.invItems||[]).find(x=>x.id===t.dataset.fied);if(!iv)return;fiOpen({id:iv.id,day:iv.day,plan:iv.plan.startsWith('x:')?'':iv.plan,pname:iv.pname,nid:iv.nid,phone:iv.phone,pfile:iv.pfile,note:iv.note,discC:iv.discC,discD:iv.discD,parts:iv.parts,lines:iv.lines.map(l=>({svc:l.svc,payee:l.payee,qty:l.qty,price:l.price,init:l.init,fee0:l.fee0,why:l.why}))});return}
  if(t.dataset.fivd){const n=await uxPrompt('علت ابطال صورتحساب','','text','ابطال صورتحساب','ابطال صورتحساب');if(!n)return;try{await api('finInvVoid',{iid:t.dataset.fivd,note:n});finMsg('صورتحساب باطل شد.');finRender()}catch(err){finMsg(err.message,1)}return}});
